mapper.select:
SELECT subtask_index AS subtaskIndex, ack_json AS ackJson, accepted_at AS acceptedAt
FROM mk_journey_execution_probe_ack WHERE tenant_id = #{key.tenantId} AND environment_name = #{key.environment} AND cell_id = #{key.cell}
  AND namespace_name = #{key.namespace} AND campaign_id = #{key.campaignId} AND probe_id = #{key.probeId} ORDER BY subtask_index LIMIT 129
